     1	export interface Customer {
     2	  readonly yearsWithMHPCO: number;
     3	}
     4	
     5	export interface Item {
     6	  readonly type: string;
     7	}
     8	
     9	const PROCESSING_FEE = 5;
    10	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
    11	
    12	const MAIN_ITEM_BASE_PREMIUM_PRICE_LIST: Readonly<Record<string, number>> = {
    13	  sword: 100,
    14	  amulet: 60,
    15	  staff: 80,
    16	  potion: 40,
    17	};
    18	
    19	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
    20	const COMPONENT_BASE_PREMIUM = 25;
    21	
    22	function isComponent(item: Item): boolean {
    23	  return COMPONENT_TYPES.includes(item.type);
    24	}
    25	
    26	function basePremiumOf(item: Item): number {
    27	  if (isComponent(item)) {
    28	    return COMPONENT_BASE_PREMIUM;
    29	  }
    30	  return MAIN_ITEM_BASE_PREMIUM_PRICE_LIST[item.type] ?? 0;
    31	}
    32	
    33	function policyBasePremiumOf(items: readonly Item[]): number {
    34	  return items.reduce((total, item) => total + basePremiumOf(item), 0);
    35	}
    36	
    37	function firstInsuranceSurchargeOn(policyBasePremium: number): number {
    38	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
    39	}
    40	
    41	function roundInOfficesFavour(premium: number): number {
    42	  return Math.ceil(premium);
    43	}
    44	
    45	export function quote(customer: Customer, items: readonly Item[]): number {
    46	  const policyBasePremium = policyBasePremiumOf(items);
    47	  return roundInOfficesFavour(
    48	    policyBasePremium + firstInsuranceSurchargeOn(policyBasePremium) + PROCESSING_FEE,
    49	  );
    50	}
