     1	import { describe, expect, it } from "vitest";
     2	import { quote } from "./claim-office.js";
     3	
     4	describe("MHPCO claim office", () => {
     5	  // --- Base premiums per item type (price list) ---
     6	  it("quotes an empty item list as premium 5 G (processing fee only)", () => {
     7	    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
     8	  });
     9	  it("quotes a single plain sword at base 100 G -> premium 115 G (100 + 10 first insurance + 5 fee)", () => {
    10	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
    11	  });
    12	  it("quotes a single plain amulet at base 60 G -> premium 71 G (60 + 6 first insurance + 5 fee)", () => {
    13	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
    14	  });
    15	  it("quotes a single plain staff at base 80 G -> premium 93 G (80 + 8 first insurance + 5 fee)", () => {
    16	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }])).toBe(93);
    17	  });
    18	  it("quotes a single plain potion at base 40 G -> premium 49 G (40 + 4 first insurance + 5 fee)", () => {
    19	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }])).toBe(49);
    20	  });
    21	  it("quotes a single rune component at base 25 G -> premium 33 G (25 + 2.5 first insurance = 27.5 -> 5 fee -> 32.5 rounded up to 33)", () => {
    22	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }])).toBe(33);
    23	  });
    24	  it("quotes a single moonstone component at base 25 G -> premium 33 G", () => {
    25	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }])).toBe(33);
    26	  });
    27	
    28	  // --- Building block of 3 alike components ---
    29	  it("quotes 2 runes as base premium 50 G (no block)", () => {
    30	    // observed through quote: 50 base + 5 first insurance + 5 fee = 60
    31	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }])).toBe(60);
    32	  });
    33	  it.todo("quotes 3 runes as base premium 60 G (block applies)");
    34	  it.todo("quotes 4 runes as base premium 100 G (no block -- block requires exactly 3)");
    35	  it.todo("quotes 7 runes as base premium 175 G (no block -- block requires exactly 3)");
    36	
    37	  // --- "Alike" components means exactly the same type ---
    38	  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types)");
    39	  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks of alike types)");
    40	
    41	  // --- Item-specific modifiers ---
    42	  it.todo("adds a 50% curse surcharge to a cursed item's base premium (cursed sword: 100 + 50)");
    43	  it.todo("adds a 30% high-enchantment surcharge for enchantment 5 (sword: 100 + 30)");
    44	  it.todo("adds no high-enchantment surcharge for enchantment 4 (sword: base 100 only)");
    45	  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 (100 + 50 + 30)");
    46	
    47	  // --- Modifier scope on multi-item policies ---
    48	  it.todo("applies the curse surcharge only to the cursed item's base premium: cursed sword + plain amulet -> 160 base + 50 curse = 210 G before policy modifiers and fee");
    49	
    50	  // --- Policy-wide modifiers ---
    51	  it.todo("applies a 20% loyalty discount for a customer with exactly 2 years with MHPCO");
    52	  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
    53	  it.todo("applies a 10% first-insurance surcharge on the policy base premium of every quote");
    54	  it.todo("applies a 15% follow-up discount on each contract after the customer's first quote in the scenario");
    55	  it.todo("adds the 5 G processing fee at the very end of every premium");
    56	
    57	  // --- Rounding in MHPCO's favour ---
    58	  it.todo("rounds a premium of 197.5 G up to 198 G");
    59	  it.todo("rounds a payout of 350.5 G down to 350 G");
    60	
    61	  // --- Integration premium examples ---
    62	  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) as premium 165 G");
    63	  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as premium 160 G");
    64	
    65	  // --- Insurance sum and cap ---
    66	  it.todo("reports a policy covering a sword and an amulet as insurance sum 1600 G with cap 3200 G");
    67	  it.todo("reports a policy covering two swords as insurance sum 2000 G with cap 4000 G");
    68	  it.todo("bases the cap on unmodified insurance values: cursed sword (premium 165 G) still has cap 2000 G");
    69	  it.todo("reports a policy covering a sword and 3 runes as insurance sum 1750 G (block discount affects premium only), cap 3500 G");
    70	
    71	  // --- Standard claim reimbursement and deductible ---
    72	  it.todo("pays out 400 G for a steel sword (enchantment 3) with 500 G damage (full reimbursement minus 100 G deductible)");
    73	  it.todo("pays out 100 G for a rune (no enchantment or material) with 200 G damage (full reimbursement minus 100 G deductible)");
    74	  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G damage -> payout 600 G");
    75	  it.todo("treats each damages entry for the same item type as a separate damage with its own deductible (two swords, 500 G each -> 800 G)");
    76	
    77	  // --- Special claim clauses ---
    78	  it.todo("reimburses damage to an item with enchantment >= 8 at 50% before the deductible (steel sword enchantment 9, 1000 G -> 400 G)");
    79	  it.todo("applies the high-enchantment clause at exactly enchantment 8 (dragon sword, 1000 G damage -> 400 G)");
    80	  it.todo("fully reimburses dragon-material damage before the deductible (dragon sword enchantment 5, 800 G -> 700 G)");
    81	  it.todo("lets the 50% high-enchantment rule win over dragon material (dragon sword enchantment 9, 1000 G -> 400 G)");
    82	
    83	  // --- Cap exhaustion across successive claims ---
    84	  it.todo("reports remainingCap after a claim: sword policy (cap 2000 G), claim 1500 G -> payout 1400 G, remainingCap 600 G");
    85	  it.todo("reduces a later payout to the remaining cap: second claim of 1500 G -> payout 600 G, remainingCap 0 G");
    86	
    87	  // --- CLI contract ---
    88	  it.todo("CLI reads a scenario from stdin and writes {results:[...]} to stdout in step order");
    89	  it.todo("CLI result for a quote step contains only premium; for a claim step contains payout and remainingCap");
    90	
    91	  // --- Rejections: CLI exits non-zero and writes an error description to stderr (adopted reading: domain throws Error, CLI maps to exit code 1 + stderr) ---
    92	  it.todo("rejects a quote containing an item of unknown type (e.g. broomstick) -- throws Error, CLI exits non-zero with stderr description and no results on stdout");
    93	  it.todo("rejects a claim whose damage item is not part of the policy (amulet damaged when only a sword is insured) -- throws Error, CLI exits non-zero with stderr description");
    94	  it.todo("rejects a claim whose damage item has an unknown type -- throws Error, CLI exits non-zero with stderr description");
    95	  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- throws Error, CLI exits non-zero with stderr description");
    96	  it.todo("rejects a claim containing a damage entry with a negative amount (-200) -- throws Error, CLI exits non-zero with stderr description");
    97	  it.todo("rejects a claim referencing a policy step index that is not a quote -- throws Error, CLI exits non-zero with stderr description");
    98	});
